(()=>{
MacHost.init();SteamDemo.init();
let open=false;
const pages=[['library','游戏库'],['discovery','发现'],['detail','游戏详情'],['settings','设置 · 常规'],['steam-settings','设置 · Steam']];
const scenarios=[['first','首次进入'],['legacy','旧版已登录升级'],['prepare','组件下载中'],['login','扫码 / 密码登录'],['ready','已登录 / Steam 游戏库'],['big','大屏模式'],['panel','悬浮球面板'],['accounts','账号管理'],['download-error','组件下载失败'],['network-error','网络连接失败'],['sync-error','游戏同步失败'],['empty','空游戏库']];
function render(){document.querySelector('#demo-controls').innerHTML=`<section class="dc-panel" ${open?'':'hidden'}><header>Mac 接入方案演示<button data-dc="toggle" aria-label="收起演示工具">−</button></header><label for="dc-version">页面版本</label><select id="dc-version"><option value="new">Steam 新方案</option><option value="baseline" ${MacHost.getState().baseline?'selected':''}>重构版原页面</option></select><label for="dc-page">宿主页面</label><select id="dc-page"><option value="">选择页面</option>${pages.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><label for="dc-state">接入状态</label><select id="dc-state"><option value="">选择场景</option>${scenarios.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><div class="dc-actions"><button data-dc="reopen">模拟重开 App</button><button data-dc="reset">重置演示</button></div><p>基于 Mac 1.0.0 重构包。账号、登录、下载及游戏运行均为模拟。浏览器刷新重置。</p></section><button class="dc-toggle" data-dc="toggle">${open?'收起演示工具':'演示工具'}</button>`;}
document.querySelector('#demo-controls').addEventListener('click',e=>{const a=e.target.closest('[data-dc]')?.dataset.dc;if(!a)return;if(a==='toggle'){open=!open;render();}if(a==='reset'){SteamDemo.reset();MacHost.reset();render();}if(a==='reopen'){SteamDemo.close?.();const s=MacHost.getState();if(s.landing==='steam')SteamDemo.enter({});else MacHost.navigate(s.landing||'discovery');}});
document.querySelector('#demo-controls').addEventListener('change',e=>{if(e.target.id==='dc-version'){SteamDemo.close?.();MacHost.setBaseline(e.target.value==='baseline');}if(e.target.id==='dc-page'){SteamDemo.close?.();MacHost.navigate(e.target.value);}if(e.target.id==='dc-state'){MacHost.setBaseline(false);SteamDemo.scenario(e.target.value);}});
window.MacReview={setOpen(v){open=v;render();},show(page){SteamDemo.close?.();MacHost.navigate(page);},scene(key){MacHost.setBaseline(false);SteamDemo.scenario(key);},baseline(v){SteamDemo.close?.();MacHost.setBaseline(v);render();}};
const q=new URLSearchParams(location.search);if(q.get('baseline')==='1')MacHost.setBaseline(true);if(q.get('page'))MacHost.navigate(q.get('page'));if(q.get('scene'))SteamDemo.scenario(q.get('scene'));render();
})();
